const res = await fetch("{{BASE_URL}}/v1/rerank", {
  method: "POST",
  headers: {
    "Authorization": "Bearer {{API_KEY}}",
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "{{MODEL}}",
    query: "如何保持健康的作息？",
    documents: [
      "每天保证 7 到 8 小时睡眠。",
      "Python 是一种编程语言。",
      "规律运动有助于改善睡眠质量。",
    ],
    top_n: 2,
  }),
});

const data = await res.json();
if (!res.ok) throw new Error(data.error?.message);
data.results.forEach((r) => console.log(r.index, r.relevance_score));

